:root {
  --bg-ticket: #0d0d2b;
  --bg-header: #12123a;
  --bg-footer: #0a0a20;
  --accent-purple: #7c5cbf;
  --accent-gold: #f5c842;
  --accent-teal: #3fd6c8;
  --accent-low: #4ecb71;
  --text-primary: #e8e4ff;
  --text-muted: #8880b0;
  --text-label: #6a6490;
  --border-color: #2a2860;
  --bar-color: #e8e4ff;
  --divider-color: #2a2860;
}

article.ticket {
  width: 460px;
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  background-color: var(--bg-ticket);
  margin: 0 auto;
}

.ticket-header {
  background-color: var(--bg-header);
  padding: 10px 16px 10px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.event-badge {
  display: inline-block;
  align-self: flex-start;
  background-color: var(--accent-purple);
  color: var(--text-primary);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  padding: 2px 7px;
  border-radius: 4px;
  margin-bottom: 3px;
}

.event-title {
  font-size: 19px;
  font-weight: 800;
  color: var(--accent-gold);
  margin: 0;
  line-height: 1.1;
}

.event-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
}

.ticket-body {
  padding: 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.info-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background-color: var(--bg-header);
  border: 1px solid var(--border-color);
  border-radius: 7px;
  padding: 6px 8px;
}

.info-label {
  font-size: 10px;
  color: var(--text-label);
  font-weight: 600;
}

.info-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-primary);
}

.forecast-row {
  display: flex;
  gap: 6px;
}

.forecast-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  background-color: var(--bg-header);
  border: 1px solid var(--border-color);
  border-radius: 7px;
  padding: 6px 4px;
}

.forecast-icon {
  font-size: 16px;
}

.forecast-label {
  font-size: 10px;
  color: var(--text-label);
  font-weight: 600;
}

.forecast-val {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-teal);
}

.forecast-val.low {
  color: var(--accent-low);
}

.ticket-footer {
  background-color: var(--bg-footer);
  border-top: 1px dashed var(--divider-color);
  padding: 9px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.ticket-left,
.ticket-right {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 52px;
}

.seat-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: var(--text-label);
}

.seat-value {
  font-size: 14px;
  font-weight: 800;
  color: var(--accent-gold);
}

.ticket-divider {
  width: 1px;
  height: 42px;
  background-color: var(--divider-color);
}

.ticket-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  flex: 1;
}

.barcode {
  display: flex;
  align-items: flex-end;
  gap: 2px;
  height: 26px;
}

.bar {
  width: 3px;
  height: 100%;
  background-color: var(--bar-color);
  border-radius: 1px;
}

.bar.wide {
  width: 6px;
}

.bar.slim {
  width: 2px;
  height: 75%;
}

.barcode-num {
  font-size: 9px;
  letter-spacing: 1px;
  color: var(--text-muted);
  font-weight: 600;
}
